19	type actionError string
20	
21	func (e actionError) Is(target error) bool { return target == ErrInvalidAction }
22	func (e actionError) Error() string        { return string(e) }
23	
24	type executionError struct{ reason string }
25	
26	func (e *executionError) Is(target error) bool { return target == ErrExecutionRejected }
27	func (e *executionError) Error() string        { return "execution rejected: " + e.reason }
28	
29	func execReject(reason string) error { return &executionError{reason: reason} }
30	
31	// ParseTransfer 解析 transfer:<账户>:<金额>。
32	// 收款账户不能为空或包含冒号；金额只接受十进制数字表示的正整数，
33	// 且必须落在有符号 64 位整数范围内。
34	func ParseTransfer(action string) (account string, amount int64, err error) {
35		parts := strings.Split(action, ":")
36		if len(parts) != 3 || parts[0] != "transfer" {
37			return "", 0, actionError("malformed action: expected transfer:<account>:<amount>, got " + strconv.Quote(action))
38		}
39		if parts[1] == "" {
40			return "", 0, actionError("malformed action: recipient account is empty")
41		}
42		amount, err = parsePositiveInt64(parts[2])
43		if err != nil {
44			return "", 0, err
45		}
46		return parts[1], amount, nil
47	}
48	
49	// parsePositiveInt64 只接受纯十进制数字、值为正且不超过 math.MaxInt64。
50	func parsePositiveInt64(s string) (int64, error) {
51		if s == "" {
52			return 0, actionError("malformed action: amount must be a positive integer")
53		}
54		for i := 0; i < len(s); i++ {
55			if s[i] < '0' || s[i] > '9' {
56				return 0, actionError("malformed action: amount must be decimal digits only, got " + strconv.Quote(s))
57			}
58		}
59		value, err := strconv.ParseInt(s, 10, 64)
60		if err != nil || value <= 0 {
61			// 纯数字串只会因超长越界走到这里（math.MaxInt64 = 9223372036854775807）。
62			return 0, actionError("malformed action: amount must be a positive integer within int64, got " + strconv.Quote(s))
63		}
64		return value, nil
65	}
66	
67	// addInt64 返回 a+b，结果超出有符号 64 位整数范围时 ok 为 false。
68	func addInt64(a, b int64) (int64, bool) {
69		if b > 0 && a > math.MaxInt64-b {
70			return 0, false
71		}
72		if b < 0 && a < math.MinInt64-b {
73			return 0, false
74		}
75		return a + b, true
76	}
