386	// ---- 执行 ----
387	
388	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
389	type executionTarget struct {
390		state        string
391		timelockEnd  int64
392		actions      []string
393		markExecuted func()
394	}
395	
396	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
397	func resolveExecutable(state *storedState, id string) *executionTarget {
398		if p, ok := state.Proposals[id]; ok {
399			return &executionTarget{
400				state:        p.State,
401				timelockEnd:  p.TimelockEnd,
402				actions:      p.Actions,
403				markExecuted: func() { p.State = "executed" },
404			}
405		}
406		if vp, ok := state.VoteProposals[id]; ok {
407			return &executionTarget{
408				state:        vp.State,
409				timelockEnd:  vp.TimelockEnd,
410				actions:      vp.Actions,
411				markExecuted: func() { vp.State = "executed" },
412			}
413		}
414		return nil
415	}
416	
417	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
418	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
419		if p, ok := state.Proposals[id]; ok {
420			return p.State, p.TimelockEnd, p.Actions, true
421		}
422		if vp, ok := state.VoteProposals[id]; ok {
423			return vp.State, vp.TimelockEnd, vp.Actions, true
424		}
425		return "", 0, nil, false
426	}
427	
428	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
429	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
430	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
431	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
432	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
433	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
434		commit, err := s.begin()
435		if err != nil {
436			return nil, err
437		}
438		defer commit()
439	
440		state, err := s.loadLocked()
441		if err != nil {
442			return nil, err
443		}
444		target := resolveExecutable(state, id)
445		if target == nil {
446			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
447		}
448		if target.state == "executed" {
449			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
450				return cloneReceipt(rcpt), nil
451			}
452			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
453		}
454		if target.state != "passed" {
455			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
456		}
457		if now < target.timelockEnd {
458			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
459		}
460		if len(target.actions) == 0 {
461			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
462		}
463	
464		// 第一阶段：在副本上校验并预演全部动作。任何一步失败都不得落盘。
465		type step struct {
466			account        string
467			amount         int64
468			treasuryBefore int64
469			treasuryAfter  int64
470			accountBefore  int64
471			accountAfter   int64
472		}
473		simTreasury := state.Treasury
474		simBalances := map[string]int64{}
475		for k, v := range state.Balances {
476			simBalances[k] = v
477		}
478		steps := make([]step, 0, len(target.actions))
479		for i, raw := range target.actions {
480			account, amount, perr := ParseTransfer(raw)
481			if perr != nil {
482				// 双 %w：调用方既可按 ErrExecutionRejected 判定执行被拒，
483				// 也可按 ErrInvalidAction 区分“动作格式错误”这一具体原因。
484				return nil, fmt.Errorf("%w: action %d (%q): %w", ErrExecutionRejected, i, raw, perr)
485			}
486			balanceBefore := simBalances[account]
487			balanceAfter, ok := addInt64(balanceBefore, amount)
488			if !ok {
489				return nil, execReject(fmt.Sprintf("recipient balance overflow at action %d: account=%s balance=%d amount=%d", i, account, balanceBefore, amount))
490			}
491			if simTreasury < amount {
492				return nil, execReject(fmt.Sprintf("insufficient treasury balance at action %d: treasury=%d amount=%d", i, simTreasury, amount))
493			}
494			treasuryBefore := simTreasury
495			simTreasury -= amount
496			simBalances[account] = balanceAfter
497			steps = append(steps, step{
498				account:        account,
499				amount:         amount,
500				treasuryBefore: treasuryBefore,
501				treasuryAfter:  simTreasury,
502				accountBefore:  balanceBefore,
503				accountAfter:   balanceAfter,
504			})
505		}
506	
507		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
508		receipt := &Receipt{
509			ProposalID: id,
510			ExecutedAt: now,
511			Order:      len(state.Receipts),
512			Actions:    make([]ActionReceipt, 0, len(steps)),
513		}
514		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
515		// executed_at 判定时不会把本进程新建的凭据误判为字段缺失。
516		receipt.executedAtRaw, _ = json.Marshal(now)
517		for i, st := range steps {
518			receipt.Actions = append(receipt.Actions, ActionReceipt{
519				Index:  i,
520				Action: target.actions[i],
521				Treasury: BalanceUpdate{
522					Account: "treasury",
523					Before:  st.treasuryBefore,
524					After:   st.treasuryAfter,
525				},
526				Recipient: BalanceUpdate{
527					Account: st.account,
528					Before:  st.accountBefore,
529					After:   st.accountAfter,
530				},
531			})
532		}
533		state.Treasury = simTreasury
534		state.Balances = simBalances
535		target.markExecuted()
536		state.Receipts = append(state.Receipts, receipt)
537	
538		if err := s.commitLocked(state); err != nil {
539			return nil, err
540		}
541		return cloneReceipt(receipt), nil
542	}
543	
544	func findReceipt(receipts []*Receipt, id string) *Receipt {
545		for _, r := range receipts {
546			if r.ProposalID == id {
547				return r
548			}
549		}
550		return nil
551	}
552	
553	func cloneReceipt(r *Receipt) *Receipt {
554		if r == nil {
555			return nil
556		}
557		copied := *r
558		if r.Actions != nil {
559			copied.Actions = make([]ActionReceipt, len(r.Actions))
560			copy(copied.Actions, r.Actions)
561		}
562		return &copied
563	}
