581			return nil, err
582		}
583		out := &BalanceSnapshot{
584			Treasury: state.Treasury,
585			Balances: make(map[string]int64, len(state.Balances)),
586		}
587		for k, v := range state.Balances {
588			out.Balances[k] = v
589		}
590		return out, nil
591	}
