624	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
625	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
626		state, err := s.readState()
627		if err != nil {
628			return ProposalRecord{}, false, err
629		}
630		p, ok := state.Proposals[id]
631		if !ok {
632			return ProposalRecord{}, false, nil
633		}
634		return toProposalRecord(p), true, nil
635	}
