637	// Proposals 返回全部已登记提案，按编号排序。
638	func (s *Store) Proposals() ([]ProposalRecord, error) {
639		state, err := s.readState()
640		if err != nil {
641			return nil, err
642		}
643		return proposalRecords(state), nil
644	}
