646	func proposalRecords(state *storedState) []ProposalRecord {
647		out := make([]ProposalRecord, 0, len(state.Proposals))
648		for _, p := range state.Proposals {
649			out = append(out, toProposalRecord(p))
650		}
651		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
652		return out
653	}
