655	// ProposalsSnapshot 是同一份完整已提交状态下的登记提案与投票提案列表。
656	// 一次 ProposalsSnapshot 调用只读取一次状态文件，保证两个来源的提案状态、
657	// 动作与投票明细彼此一致：不会把不同提交时刻的提案状态拼在一起。
658	type ProposalsSnapshot struct {
659		Registered []ProposalRecord    `json:"registered"`
660		Voting     []*VoteProposalView `json:"voting"`
661	}
662	
663	// ProposalsSnapshot 在一次持锁读取中取得全部登记提案与全部投票提案。
664	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
665	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
666	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
667		state, err := s.readState()
668		if err != nil {
669			return nil, err
670		}
671		return &ProposalsSnapshot{
672			Registered: proposalRecords(state),
673			Voting:     voteProposalViews(state),
674		}, nil
675	}
