687	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
688		state, err := s.readState()
689		if err != nil {
690			return nil, false, err
691		}
692		r := findReceipt(state.Receipts, id)
693		if r == nil {
694			return nil, false, nil
695		}
