699	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
700	func (s *Store) Receipts() ([]*Receipt, error) {
701		state, err := s.readState()
702		if err != nil {
703			return nil, err
704		}
705		out := make([]*Receipt, 0, len(state.Receipts))
706		for _, r := range state.Receipts {
707			out = append(out, cloneReceipt(r))
