721	// ---- 持久化 ----
722	
723	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
724	func (s *Store) loadLocked() (*storedState, error) {
725		raw, err := os.ReadFile(s.path)
726		if err != nil {
727			return nil, err
728		}
729		if len(bytes.TrimSpace(raw)) == 0 {
730			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
731		}
732		if err := checkStateStructure(raw); err != nil {
733			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
734		}
735		var state storedState
736		dec := json.NewDecoder(bytes.NewReader(raw))
737		dec.DisallowUnknownFields()
738		if err := dec.Decode(&state); err != nil {
739			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
740		}
741		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
742		var extra json.RawMessage
743		if err := dec.Decode(&extra); err != io.EOF {
744			if err == nil {
745				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
746			}
747			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
748		}
749		if err := validateState(&state); err != nil {
750			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
751		}
752		return &state, nil
753	}
754	
755	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
756	// 任一步失败都保留上次完整状态。调用方必须持锁。
757	func (s *Store) commitLocked(state *storedState) error {
758		if err := validateState(state); err != nil {
759			return fmt.Errorf("refusing to persist invalid state: %w", err)
760		}
761		payload, err := json.MarshalIndent(state, "", "  ")
762		if err != nil {
763			return err
764		}
765		payload = append(payload, '\n')
766	
767		dir := filepath.Dir(s.path)
768		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
769		if err != nil {
770			return err
771		}
772		tmpName := tmp.Name()
773		cleanup := func() { _ = os.Remove(tmpName) }
774		if _, err := tmp.Write(payload); err != nil {
775			_ = tmp.Close()
776			cleanup()
777			return err
778		}
779		if err := tmp.Sync(); err != nil {
780			_ = tmp.Close()
781			cleanup()
782			return err
783		}
784		if err := tmp.Close(); err != nil {
785			cleanup()
786			return err
787		}
788		if err := os.Chmod(tmpName, 0o600); err != nil {
789			cleanup()
790			return err
791		}
792		if err := os.Rename(tmpName, s.path); err != nil {
793			cleanup()
794			return err
795		}
796		if err := syncDir(dir); err != nil {
797			return err
798		}
799		return nil
800	}
801	
802	func syncDir(dir string) error {
803		d, err := os.Open(dir)
804		if err != nil {
805			return err
806		}
807		defer d.Close()
808		return d.Sync()
809	}
810	
811	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
812	func validateState(state *storedState) error {
813		if state.Magic != stateMagic {
814			return fmt.Errorf("bad magic %q", state.Magic)
815		}
816		if state.Version != stateVersion {
817			return fmt.Errorf("unsupported state version %d", state.Version)
818		}
819		if state.InitialTreasury < 0 {
820			return errors.New("initial treasury balance is negative")
821		}
822		if state.Treasury < 0 {
823			return errors.New("treasury balance is negative")
824		}
825		if state.Balances == nil {
826			return errors.New("balances table is missing")
827		}
828		if state.Proposals == nil {
829			return errors.New("proposals table is missing")
830		}
831		if state.Receipts == nil {
832			return errors.New("receipts table is missing")
833		}
834		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
835		if state.VoteProposals == nil {
836			state.VoteProposals = map[string]*storedVoteProposal{}
837		}
838		for account, balance := range state.Balances {
839			if account == "" {
840				return errors.New("balance entry with empty account")
841			}
842			if balance < 0 {
843				return fmt.Errorf("balance of %q is negative", account)
844			}
845		}
846		for key, p := range state.Proposals {
847			if p == nil {
848				return fmt.Errorf("proposal %q is empty", key)
849			}
850			if p.ID != key || p.ID == "" {
851				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
852			}
853			if p.State != "passed" && p.State != "executed" {
854				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
855			}
856			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
857		}
858		if err := validateVoteProposals(state); err != nil {
859			return err
860		}
861	
862		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
863		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
864		simTreasury := state.InitialTreasury
865		simBalances := map[string]int64{}
866		seenReceipts := map[string]int{}
867		for order, rcpt := range state.Receipts {
868			if rcpt == nil {
869				return fmt.Errorf("receipt %d is empty", order)
870			}
871			if rcpt.Order != order {
872				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
873			}
874			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
875				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
876			}
877			seenReceipts[rcpt.ProposalID] = order
878			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
879			if !found {
880				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
881			}
882			if ownerState != "executed" {
883				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
884			}
885			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
886			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
887			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
888				return err
889			}
890			if len(rcpt.Actions) != len(ownerActions) {
891				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(ownerActions))
892			}
893			for i, ar := range rcpt.Actions {
894				if ar.Index != i {
895					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
896				}
897				if ar.Action != ownerActions[i] {
898					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
899				}
900				account, amount, err := ParseTransfer(ar.Action)
901				if err != nil {
902					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
903				}
904				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
905					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
906				}
907				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
908					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
909				}
910				before := simBalances[account]
911				if ar.Recipient.Account != account || ar.Recipient.Before != before {
912					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
913				}
914				after, ok := addInt64(before, amount)
915				if !ok || ar.Recipient.After != after {
916					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
917				}
918				simTreasury -= amount
919				simBalances[account] = after
920			}
921		}
922		if simTreasury != state.Treasury {
923			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
924		}
925		if len(simBalances) != len(state.Balances) {
926			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
927		}
928		for account, balance := range state.Balances {
929			if simBalances[account] != balance {
930				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
931			}
932		}
933		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
934		for _, p := range state.Proposals {
935			_, hasReceipt := seenReceipts[p.ID]
936			if p.State == "executed" && !hasReceipt {
937				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
938			}
939		}
940		for _, p := range state.VoteProposals {
941			_, hasReceipt := seenReceipts[p.ID]
942			if p.State == "executed" && !hasReceipt {
943				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
944			}
945		}
946		return nil
947	}
948	
949	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
950	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
951	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
952	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
953	// 位置（0 起），与提案编号一起用于定位。
954	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
955		raw := rcpt.executedAtRaw
956		switch {
957		case raw == nil:
958			return fmt.Errorf("receipt %d for proposal %q field %q is missing", order, rcpt.ProposalID, "executed_at")
959		case string(raw) == "null":
960			return fmt.Errorf("receipt %d for proposal %q field %q is null", order, rcpt.ProposalID, "executed_at")
961		case !isInt64Number(raw):
962			return fmt.Errorf("receipt %d for proposal %q field %q has wrong type: want integer, got %s",
963				order, rcpt.ProposalID, "executed_at", jsonValueType(raw))
964		}
965		if rcpt.ExecutedAt < timelockEnd {
966			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
967				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
968		}
969		return nil
970	}
971	
972	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
973	
974	// schemaKind 是状态文件 JSON 在某一层的形状类别。
975	type schemaKind int
976	
977	const (
978		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
979		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
980		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
981		kindArray                     // 数组
982		kindString                    // 叶子：必须是 JSON 字符串
983		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
984		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
985	)
986	
987	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
988	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
989	type schemaNode struct {
990		kind   schemaKind
991		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
992		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
993	}
994	
995	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
996	func schemaOf(t reflect.Type) *schemaNode {
997		for t.Kind() == reflect.Pointer {
998			t = t.Elem()
999		}
1000		switch t.Kind() {
1001		case reflect.Struct:
1002			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1003			for i := 0; i < t.NumField(); i++ {
1004				f := t.Field(i)
1005				if f.PkgPath != "" { // 未导出字段不参与 JSON
1006					continue
1007				}
1008				name := f.Name
1009				if tag, ok := f.Tag.Lookup("json"); ok {
1010					tagName, _, _ := strings.Cut(tag, ",")
1011					if tagName == "-" {
1012						continue
1013					}
1014					if tagName != "" {
1015						name = tagName
1016					}
1017				}
1018				node.fields[name] = schemaOf(f.Type)
1019			}
1020			return node
1021		case reflect.Map:
1022			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1023		case reflect.Slice, reflect.Array:
1024			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1025		case reflect.String:
1026			return &schemaNode{kind: kindString}
1027		case reflect.Bool:
1028			return &schemaNode{kind: kindBoolean}
1029		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1030			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1031			return &schemaNode{kind: kindInteger}
1032		default:
1033			return &schemaNode{kind: kindAny}
1034		}
1035	}
1036	
1037	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1038	
1039	func init() {
1040		// 票据的四个标量字段（representative/weight/support/voted_at）由
1041		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1042		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1043		// 不抢在解码器之前用不含票据定位的通用信息报错。
1044		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1045		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1046			ballotFields[name].kind = kindAny
1047		}
1048		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1049		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1050		// 叶子位置保持宽松。
1051		storedStateSchema.fields["receipts"].elem.fields["executed_at"].kind = kindAny
1052	}
1053	
1054	// scanFrame 是结构扫描的栈帧。
1055	type scanFrame struct {
1056		node    *schemaNode
1057		isArray bool
1058		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1059		seen    map[string]bool
1060		atValue bool // 对象帧：下一个待消费 token 是值而非键
1061		index   int  // 数组帧：下一个元素下标
1062		path    string
1063	}
1064	
1065	func peekFrame(stack []*scanFrame) *scanFrame {
1066		if len(stack) == 0 {
1067			return nil
1068		}
1069		return stack[len(stack)-1]
1070	}
1071	
1072	// checkStateStructure 在解码前逐 token 扫描状态文件：
1073	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1074	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1075	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1076	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1077	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1078	//
1079	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1080	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1081	func checkStateStructure(raw []byte) error {
1082		dec := json.NewDecoder(bytes.NewReader(raw))
1083		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1084		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1085		dec.UseNumber()
1086		var stack []*scanFrame
1087		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1088		pendingNode := storedStateSchema
1089		pendingPath := "state"
1090	
1091		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1092		finishValue := func() {
1093			top := peekFrame(stack)
1094			if top == nil || top.opaque {
1095				return
1096			}
1097			if top.isArray {
1098				top.index++
1099			} else {
1100				top.atValue = false
1101			}
1102		}
1103	
1104		for {
1105			tok, err := dec.Token()
1106			if err == io.EOF {
1107				if len(stack) != 0 {
1108					return errors.New("unterminated object or array")
1109				}
1110				return nil
1111			}
1112			if err != nil {
1113				return err
1114			}
1115	
1116			if top := peekFrame(stack); top != nil && top.opaque {
1117				// 不透明容器内不做字段检查，只配对括号。
1118				if d, ok := tok.(json.Delim); ok {
1119					if d == '{' || d == '[' {
1120						stack = append(stack, &scanFrame{opaque: true})
1121					} else {
1122						stack = stack[:len(stack)-1]
1123						finishValue()
1124					}
1125				}
1126				continue
1127			}
1128	
1129			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1130				// 对象帧的键位置：闭括号或下一个键。
1131				if d, ok := tok.(json.Delim); ok {
1132					if d != '}' {
1133						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1134					}
1135					stack = stack[:len(stack)-1]
1136					finishValue()
1137					continue
1138				}
1139				key, ok := tok.(string)
1140				if !ok {
1141					return errors.New("object key must be a string")
1142				}
1143				if top.seen[key] {
1144					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1145				}
1146				top.seen[key] = true
1147				top.atValue = true
1148				switch top.node.kind {
1149				case kindObject:
1150					child, known := top.node.fields[key]
1151					if !known {
1152						return fmt.Errorf("unknown field %q at %s", key, top.path)
1153					}
1154					pendingNode = child
1155					pendingPath = top.path + "." + key
1156				case kindMap:
1157					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1158					pendingNode = top.node.elem
1159					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1160				}
1161				continue
1162			}
1163	
1164			// 值位置：对象键之后的值或数组元素。
1165			node := pendingNode
1166			path := pendingPath
1167			if top := peekFrame(stack); top != nil && top.isArray {
1168				node = top.node.elem
1169				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1170			}
1171			if d, ok := tok.(json.Delim); ok {
1172				switch d {
1173				case '{', '[':
1174					frame := &scanFrame{isArray: d == '[', path: path}
1175					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1176						(d == '[' && node.kind == kindArray)
1177					if !shapeOK {
1178						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1179						frame.opaque = true
1180					} else {
1181						frame.node = node
1182						if d == '{' {
1183							frame.seen = map[string]bool{}
1184						}
1185					}
1186					stack = append(stack, frame)
1187				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1188					if len(stack) == 0 {
1189						return errors.New("unexpected closing delimiter")
1190					}
1191					stack = stack[:len(stack)-1]
1192					finishValue()
1193				}
1194				continue
1195			}
1196			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1197			// null 不允许用来顶替字符串/布尔/整数。
1198			if err := checkLeafScalar(node, path, tok); err != nil {
1199				return err
1200			}
1201			finishValue()
1202		}
1203	}
1204	
1205	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1206	func leafKindName(k schemaKind) string {
1207		switch k {
1208		case kindString:
1209			return "string"
1210		case kindBoolean:
1211			return "boolean"
1212		case kindInteger:
1213			return "integer"
1214		default:
1215			return "value"
1216		}
1217	}
1218	
1219	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1220	func tokenKindName(tok json.Token) string {
1221		switch v := tok.(type) {
1222		case nil:
1223			return "null"
1224		case string:
1225			return "string"
1226		case bool:
1227			return "boolean"
1228		case json.Number:
1229			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1230				return "integer"
1231			}
1232			return "number"
1233		default:
1234			return "value"
1235		}
1236	}
1237	
1238	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1239	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1240	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1241		switch node.kind {
1242		case kindString, kindBoolean, kindInteger:
1243		default:
1244			return nil
1245		}
1246		if node.kind == kindInteger {
1247			if n, ok := tok.(json.Number); ok {
1248				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1249					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1250				}
1251				return nil
1252			}
1253		}
1254		want := leafKindName(node.kind)
1255		if got := tokenKindName(tok); got != want {
1256			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1257		}
1258		return nil
1259	}
1260

