24	// ---- 输入与对外视图 ----
25	
26	// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
27	type VoteMember struct {
28		ID     string `json:"id"`
29		Weight int64  `json:"weight"`
30	}
