51	// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
52	type MemberView struct {
53		ID       string   `json:"id"`
54		Weight   int64    `json:"weight"`
55		Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
56		Delegate string   `json:"delegate"`  // 最终代表
