68	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
69	type TallyResultView struct {
70		ForWeight     int64 `json:"for_weight"`
71		AgainstWeight int64 `json:"against_weight"`
72		Turnout       int64 `json:"turnout"`
73		Quorum        int64 `json:"quorum"`
74		Passed        bool  `json:"passed"`
75		TalliedAt     int64 `json:"tallied_at"`
76	}
