368	// removeLineContaining 删除文本中包含子串的整行（含行尾换行）。
369	func removeLineContaining(s, substr string) string {
370		idx := strings.Index(s, substr)
371		if idx < 0 {
372			return s
373		}
374		start := strings.LastIndex(s[:idx], "\n") + 1
375		end := strings.Index(s[idx:], "\n")
376		if end < 0 {
377			return s[:start]
378		}
379		return s[:start] + s[idx+end+1:]
380	}
