596	// dupKeyInject 在 balances 对象里注入一个重复键。
597	func dupKeyInject(good []byte) []byte {
598		s := string(good)
599		marker := "\"balances\": {"
600		idx := strings.Index(s, marker)
601		if idx < 0 {
602			// 空 balances 被渲染成 {}，改为含重复键的对象。
603			s = strings.Replace(s, "\"balances\": {}", "\"balances\": {\"x\": 1, \"x\": 2}", 1)
604			return []byte(s)
605		}
606		insertAt := idx + len(marker)
607		return []byte(s[:insertAt] + "\"dup\": 1, " + s[insertAt:])
608	}
