470	// TestCLIRejectsIncompleteBallot：未计票提案的票据缺 support 时，文本与 JSON
471	// 查询、计票都把整份文件判为损坏：原因写入 stderr（能看出提案编号、票据与字段、
472	// 空值/缺失/类型不符），以域错误退出码 1 结束，stdout 不出现部分结果，文件不改写。
473	func TestCLIRejectsIncompleteBallot(t *testing.T) {
